package br.com.pelotavision;
import org.opencv.core.*;import org.opencv.imgproc.*;import java.util.*;import java.util.concurrent.CancellationException;import java.util.function.BooleanSupplier;
/** Detailed analysis consumes original pixels; treatments/SR only propose contours. Fits and cracks use original grayscale. */
public final class DetailedAnalysis {
 public static final long BUDGET_MS=180000;
 public static final class Report {
  public final DetailGeometry geometry;public final int tiles,baselineCount,selectedCount;public final int[] treatments;public final boolean compared,superResolution;public final long durationMs;public final String optionId;public final List<Double> tileScores;public final DetectionTuner.Report settingSearch;
  public Report(DetailGeometry g,int tiles,int base,int selected,int[] counts,boolean compared,boolean sr,long ms,String option,List<Double> scores){this(g,tiles,base,selected,counts,compared,sr,ms,option,scores,null);}
  private Report(DetailGeometry g,int tiles,int base,int selected,int[] counts,boolean compared,boolean sr,long ms,String option,List<Double> scores,DetectionTuner.Report search){settingSearch=search;geometry=g;this.tiles=tiles;baselineCount=base;selectedCount=selected;treatments=counts.clone();this.compared=compared;superResolution=sr;durationMs=ms;optionId=option;tileScores=Collections.unmodifiableList(new ArrayList<>(scores));}
  public Report withSearch(DetectionTuner.Report search){return new Report(geometry,tiles,baselineCount,selectedCount,treatments,compared,superResolution,durationMs,optionId,tileScores,search);}
  public String summary(){return "Detalhada · "+geometry.width+" × "+geometry.height+" px · "+tiles+" blocos"+(geometry.sample>1?" · leitura 1/"+geometry.sample:"")+(superResolution?" · SR 2× testada":"");}
 }
 public static final class Output {public final PelletDetector.Result result;public final CrackAnalysis cracks;public final Report report;Output(PelletDetector.Result r,CrackAnalysis c,Report d){result=r;cracks=c;report=d;}}
 public static Output run(Mat original,DetailGeometry map,DetectionTuner.Option option,boolean compare,FsrcnnUpscaler sr,Granulometry.Settings scale,int ow,int oh,double minimum,CrackModel model,int crackSensitivity,BooleanSupplier cancel,DetectionTuner.Progress progress){
  long start=System.nanoTime();List<TilePlan.Tile> tiles=TilePlan.create(original.cols(),original.rows(),sr!=null);if(tiles.size()>(sr==null?80:240))throw new IllegalArgumentException("ROI muito grande para este modo. Reduza a área selecionada.");
  List<PelletDetector.Detection> all=new ArrayList<>(),baselineAll=new ArrayList<>();int[] treatments=new int[4];List<Double> scores=new ArrayList<>();int candidates=0;boolean limit=false;
  for(TilePlan.Tile tile:tiles){check(cancel,start);Mat sub=original.submat(tile.top,tile.top+tile.height,tile.left,tile.left+tile.width);Mat gray=sub.clone();sub.release();
   try{List<PelletDetector.Result> options=new ArrayList<>();progress.update(tile.index+1,tiles.size(),"Bloco "+(tile.index+1)+" · original");PelletDetector.Result baseline=DetectionTuner.detect(gray,option);options.add(baseline);
    if(compare){for(int treatment=1;treatment<=2;treatment++){check(cancel,start);progress.update(tile.index+1,tiles.size(),"Bloco "+(tile.index+1)+" · "+(treatment==1?"contraste local":"ruído leve"));Mat enhanced=treat(gray,treatment);try{options.add(refineOriginal(gray,DetectionTuner.detect(enhanced,option),1));}finally{enhanced.release();}}}
    if(sr!=null){check(cancel,start);progress.update(tile.index+1,tiles.size(),"Bloco "+(tile.index+1)+" · FSRCNN 2× experimental");Mat enlarged=sr.upsample(gray);try{PelletDetector.Result refined=refineOriginal(gray,DetectionTuner.detect(enlarged,option),.5);List<PelletDetector.Detection> verified=new ArrayList<>();for(PelletDetector.Detection d:refined.circles){boolean matched=false;for(PelletDetector.Detection b:baseline.circles)if(TilePlan.duplicate(d,b)){matched=true;break;}verified.add(matched?d:d.flagged());}options.add(new PelletDetector.Result(verified,gray.cols(),gray.rows(),refined.candidates,refined.durationMs,refined.candidateLimit,refined.method));}finally{enlarged.release();}}
    DetectionAssessment.Context context=DetectionAssessment.Context.tile(scale,ow,oh,map.region,minimum,map,tile);for(int i=0;i<options.size();i++)options.set(i,context.filterScope(options.get(i)));DetectionEvidence evidence=DetectionEvidence.create(gray,options);List<DetectionAssessment.Metrics> metrics=new ArrayList<>();int max=0;for(PelletDetector.Result result:options){DetectionAssessment.Metrics m=DetectionAssessment.measure(result,context);metrics.add(m);max=Math.max(max,m.valid);}int best=0;double bestScore=-1;
    for(int i=0;i<options.size();i++){DetectionEvidence.Coverage coverage=evidence.coverage(evidence.map(options.get(i)),context);double score=coverage.available?DetectionAssessment.coverageScore(metrics.get(i),coverage,0,options.get(i).candidateLimit):DetectionAssessment.score(metrics.get(i),max,0,options.get(i).candidateLimit);if(i==0||score>bestScore+2){best=i;bestScore=score;}}
    PelletDetector.Result chosen=options.get(best);int treatmentId=best==0?0:best<=2&&compare?best:3;treatments[treatmentId]++;scores.add(bestScore);candidates+=chosen.candidates;limit|=chosen.candidateLimit;
    collect(baseline,tile,map,baselineAll);collect(chosen,tile,map,all);if(all.size()>6000)throw new IllegalArgumentException("ROI com muitas marcações. Reduza a área para conferir os objetos.");
   }finally{gray.release();}
  }
  check(cancel,start);List<PelletDetector.Detection> merged=TilePlan.merge(all);String method="detail_original_tiles_v1+ellipse_boundary_v1"+(map.region==null?"":"+active_roi_crop_v1")+(sr==null?"":"+fsrcnn_x2_proposals_original_refine");PelletDetector.Result nativeResult=new PelletDetector.Result(merged,map.width,map.height,candidates,(System.nanoTime()-start)/1000000,limit,method);
  progress.update(tiles.size(),tiles.size(),"Trincas nos pixels originais…");CrackAnalysis cracks=new CrackDetector(model).detect(original,nativeResult,crackSensitivity);check(cancel,start);
  List<PelletDetector.Detection> projected=new ArrayList<>();for(PelletDetector.Detection d:merged)projected.add(map.toPreview(d));PelletDetector.Result mapped=new PelletDetector.Result(projected,map.previewWidth,map.previewHeight,candidates,(System.nanoTime()-start)/1000000,limit,method);
  Report report=new Report(map,tiles.size(),TilePlan.merge(baselineAll).size(),merged.size(),treatments,compare,sr!=null,mapped.durationMs,option.id,scores);return new Output(mapped,map.toPreview(cracks),report);
 }
 static void check(BooleanSupplier cancel,long start){if(cancel.getAsBoolean()||Thread.currentThread().isInterrupted())throw new CancellationException("Análise cancelada; resultado anterior preservado.");if((System.nanoTime()-start)/1000000>BUDGET_MS)throw new IllegalArgumentException("O modo detalhado atingiu 3 minutos. Reduza a ROI e tente novamente.");}
 static Mat treat(Mat gray,int mode){Mat out=new Mat();if(mode==1){CLAHE clahe=Imgproc.createCLAHE(1.5,new Size(8,8));try{clahe.apply(gray,out);}finally{clahe.collectGarbage();clahe.clear();}}else Imgproc.bilateralFilter(gray,out,5,15,3);return out;}
 static PelletDetector.Result refineOriginal(Mat original,PelletDetector.Result proposals,double ratio){List<PelletDetector.Detection> seeds=new ArrayList<>();for(PelletDetector.Detection d:proposals.circles)seeds.add(d.affine(ratio,ratio,0,0));return new EllipseFitter().refine(original,new PelletDetector.Result(seeds,original.cols(),original.rows(),proposals.candidates,proposals.durationMs,proposals.candidateLimit,proposals.method));}
 static void collect(PelletDetector.Result result,TilePlan.Tile tile,DetailGeometry map,List<PelletDetector.Detection> out){for(PelletDetector.Detection d:result.circles){PelletDetector.Detection nativeObject=d.translated(tile.left,tile.top,false);if(!tile.owns(nativeObject.x,nativeObject.y))continue;PelletDetector.Detection display=map.toPreview(nativeObject);if(map.region!=null&&!map.region.includes(display))continue;boolean squareSafe=map.inside(nativeObject.crackX-nativeObject.crackRadius,nativeObject.crackY-nativeObject.crackRadius)&&map.inside(nativeObject.crackX+nativeObject.crackRadius,nativeObject.crackY-nativeObject.crackRadius)&&map.inside(nativeObject.crackX-nativeObject.crackRadius,nativeObject.crackY+nativeObject.crackRadius)&&map.inside(nativeObject.crackX+nativeObject.crackRadius,nativeObject.crackY+nativeObject.crackRadius);out.add(nativeObject.translated(0,0,!squareSafe));}}
}
